def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = next((v for v in counts if v != bg and v != 0), None)
    # In this task, the scattered anchor points are zeroes; the compact
    # multicolor object supplies the pattern.
    marker = 0

    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, marker)]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for pr in range(r0, r1 + 1):
                    for pc in range(c0, c1 + 1):
                        color = grid[pr][pc]
                        if color not in (bg, marker):
                            rr, cc = r + pr - ar, c + pc - ac
                            if 0 <= rr < h and 0 <= cc < w:
                                out[rr][cc] = color
    return out
